package net.civeira.phylax.features.notification.message.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.notification.message.domain.Message;
import net.civeira.phylax.features.notification.message.domain.valueobject.UrgentVO;

@RequiredArgsConstructor
public class UrgentValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<UrgentVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Boolean> getUrgent() {
    return value.map(UrgentVO::isUrgent);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<UrgentVO> getUrgentValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public UrgentVO readUrgent(final Optional<Message> original, final ConstraintFailList fails) {
    UrgentVO result = value.orElse(original.map(Message::getUrgentValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "urgent", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetUrgent() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetUrgentIfMatches(final String field) {
    if ("urgent".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param urgent
   * @return
   */
  public T urgent(UrgentVO urgent) {
    this.value = Optional.of(urgent);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param urgent
   * @return
   */
  public T urgent(Optional<UrgentVO> urgent) {
    this.value = urgent;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param urgent
   * @return
   */
  public T urgent(Boolean urgent) {
    this.value = Optional.of(UrgentVO.from(urgent));
    return this.holder;
  }
}
